begin;
-- Only the purpose-specific command can create this transaction/backend-scoped exception.
create table internal.closed_academic_write_scope(school_id uuid not null,actor_id uuid not null,submission_id uuid not null,transaction_id bigint not null,backend_pid integer not null,primary key(school_id,actor_id,submission_id,transaction_id,backend_pid));
alter table internal.closed_academic_write_scope enable row level security;alter table internal.closed_academic_write_scope force row level security;
revoke all on internal.closed_academic_write_scope from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
create table app.academic_correction_records(school_id uuid not null,id uuid not null default gen_random_uuid(),submission_id uuid not null,result_id uuid not null,previous_result_id uuid,model text not null check(model in('numeric','rubric')),reason text not null check(length(btrim(reason))between 1 and 2000),actor_id uuid not null,created_at timestamptz not null default clock_timestamp(),primary key(school_id,id),unique(school_id,result_id),foreign key(school_id,submission_id)references app.submissions(school_id,id),foreign key(school_id,actor_id)references app.memberships(school_id,actor_id));
alter table app.academic_correction_records enable row level security;alter table app.academic_correction_records force row level security;
create trigger correction_history_immutable before update or delete on app.academic_correction_records for each row execute function internal.academic_history_immutable();
create trigger correction_no_truncate before truncate on app.academic_correction_records for each statement execute function internal.academic_history_immutable();
revoke all on app.academic_correction_records from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
create or replace function internal.current_submission_academic_guard()returns trigger language plpgsql security definer set search_path=''as $$declare c app.current_submissions;begin
 select*into c from app.current_submissions where school_id=new.school_id and submission_id=new.submission_id for update;
 if not found or not"authorization".can_mark_submission(new.school_id,new.submission_id)or(c.state not in('SUBMITTED','RESUBMITTED')and not(c.state='CLOSED'and exists(select 1 from internal.closed_academic_write_scope scope where scope.school_id=new.school_id and scope.actor_id="authorization".actor_id()and scope.submission_id=new.submission_id and scope.transaction_id=txid_current()and scope.backend_pid=pg_backend_pid())))then raise exception 'Current submitted source required for academic write'using errcode='22023';end if;return new;
end$$;
create function internal.correct_closed_academic_source(target uuid,input jsonb)returns uuid language plpgsql security definer set search_path=''as $$
declare school uuid:="authorization".school_id();actor uuid:="authorization".actor_id();submission app.submissions;assessment app.assessments;pointer app.current_submissions;current_result uuid;current_revision integer;latest_mark integer;marking uuid;result uuid;reason_value text:=input->>'reason';begin
 select*into submission from app.submissions where school_id=school and id=target;
 if not found or not"authorization".academic_access(school)or not"authorization".can_mark_submission(school,target)then raise exception 'Closed academic correction denied'using errcode='42501';end if;
 perform internal.lock_academic_course(school,"authorization".assessment_course(school,submission.assessment_id));
 select*into submission from app.submissions where school_id=school and id=target for update;
 select*into pointer from app.current_submissions where school_id=school and assessment_id=submission.assessment_id and learner_id=submission.learner_id for update;
 select*into assessment from app.assessments where school_id=school and id=submission.assessment_id for share;
 if input is null or jsonb_typeof(input)<>'object'or not(input?&array['feedback','reason','expectedSubmissionRevision','expectedPolicyVersion','expectedRevision','expectedResultId','expectedResultRevision','parentVisible','sourceEvidence'])or(input-array['score','nativeResult','feedback','reason','expectedSubmissionRevision','expectedPolicyVersion','expectedRevision','expectedResultId','expectedResultRevision','parentVisible','sourceEvidence'])<>'{}'::jsonb or jsonb_typeof(input->'parentVisible')is distinct from'boolean'or jsonb_typeof(input->'feedback')is distinct from'string'or length(input->>'feedback')>10000 or pointer.submission_id is distinct from submission.id or pointer.state<>'CLOSED'or(submission.revision is distinct from(input->>'expectedSubmissionRevision')::integer)or assessment.policy_version is distinct from(input->>'expectedPolicyVersion')::integer or reason_value is null or length(btrim(reason_value))not between 1 and 2000 or input->'sourceEvidence'is distinct from'true'::jsonb or not exists(select 1 from app.school_custom_references where school_id=school and id=assessment.academic_reference_id and status='APPROVED')then raise exception 'Closed correction source changed'using errcode='22023';end if;
 if assessment.model='numeric'then select r.id,r.revision into current_result,current_revision from app.current_results p join app.result_revisions r on r.school_id=p.school_id and r.id=p.result_id where p.school_id=school and p.submission_id=target;select coalesce(max(revision),0)into latest_mark from app.marking_revisions where school_id=school and submission_id=target;
 else select r.id,r.revision into current_result,current_revision from app.current_rubric_results p join app.rubric_result_revisions r on r.school_id=p.school_id and r.id=p.result_id where p.school_id=school and p.submission_id=target;select coalesce(max(revision),0)into latest_mark from app.rubric_marking_revisions where school_id=school and submission_id=target;end if;
 if current_result is distinct from(input->>'expectedResultId')::uuid or coalesce(current_revision,0)is distinct from(input->>'expectedResultRevision')::integer or latest_mark is distinct from(input->>'expectedRevision')::integer or(current_result is null and latest_mark<>0)then raise exception 'Closed correction revision changed'using errcode='22023';end if;
 insert into internal.closed_academic_write_scope values(school,actor,target,txid_current(),pg_backend_pid());
 if assessment.model='numeric'then if input?'nativeResult'then raise exception 'Native model mismatch'using errcode='22023';end if;marking:=internal.mark_submission(target,(input->>'score')::numeric,input->>'feedback',assessment.policy_version,latest_mark,true);result:=internal.release_marking(marking,latest_mark+1,(input->>'parentVisible')::boolean);
 else if input?'score'then raise exception 'Native model mismatch'using errcode='22023';end if;marking:=internal.mark_rubric_submission(target,(input->'nativeResult'->>'rubricId')::uuid,input->'nativeResult'->'criteria',input->>'feedback',assessment.policy_version,latest_mark,true);result:=internal.release_rubric_marking(marking,latest_mark+1,(input->>'parentVisible')::boolean);end if;
 insert into app.academic_correction_records(school_id,submission_id,result_id,previous_result_id,model,reason,actor_id)values(school,target,result,current_result,assessment.model,reason_value,actor);
 delete from internal.closed_academic_write_scope where school_id=school and actor_id=actor and submission_id=target and transaction_id=txid_current()and backend_pid=pg_backend_pid();return result;
end$$;
create function internal.read_academic_revision_page(source_result uuid,page_limit integer,page_cursor uuid)returns jsonb language plpgsql security definer set search_path=''set jit='off'as $$
declare school uuid:="authorization".school_id();anchor record;rows jsonb;items jsonb;begin
 if not"authorization".academic_access(school)or page_limit is null or page_limit not between 1 and 100 then raise exception 'Academic history denied'using errcode='42501';end if;
 select id,submission_id,learner_id,assessment_id,parent_visible into anchor from(select id,submission_id,learner_id,assessment_id,parent_visible from app.result_revisions where school_id=school and id=source_result union all select id,submission_id,learner_id,assessment_id,parent_visible from app.rubric_result_revisions where school_id=school and id=source_result)source;
 if not found or not"authorization".can_read_academic_source(school,anchor.learner_id,anchor.parent_visible,anchor.assessment_id)then raise exception 'Academic history source denied'using errcode='42501';end if;
 with sources as materialized(select r.id,r.school_id,r.submission_id,r.assessment_id,r.learner_id,r.revision,r.feedback,r.policy_version,r.reference_id,r.reference_version,r.evidence_id,r.created_at,r.created_by,r.parent_visible,r.previous_result_id,'numeric'::text model,jsonb_build_object('type','numeric','score',r.score,'maxScore',r.max_score,'policyVersion',r.policy_version)native_result,r.score,r.max_score from app.result_revisions r where r.school_id=school and r.submission_id=anchor.submission_id union all select r.id,r.school_id,r.submission_id,r.assessment_id,r.learner_id,r.revision,r.feedback,r.policy_version,r.reference_id,r.reference_version,r.evidence_id,r.created_at,r.created_by,r.parent_visible,r.previous_result_id,'rubric',r.native_result,null::numeric,null::numeric from app.rubric_result_revisions r where r.school_id=school and r.submission_id=anchor.submission_id),bounded as(select*from sources source where(page_cursor is null or source.id>page_cursor)and"authorization".can_read_academic_source(school,source.learner_id,source.parent_visible,source.assessment_id)order by source.id limit page_limit+1)
 select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'submissionId',r.submission_id,'assessmentId',r.assessment_id,'learnerId',r.learner_id,'revision',r.revision,'feedback',r.feedback,'status','RELEASED','policyVersion',r.policy_version,'referenceId',r.reference_id,'referenceVersion',r.reference_version,'evidenceId',r.evidence_id,'createdAt',r.created_at,'actorId',r.created_by,'parentVisible',r.parent_visible,'nativeResult',r.native_result,'model',r.model,'assessmentTitle',a.title,'referenceTitle',ref.title,'previousResultId',case when"authorization".current_role(school)='parent'then null else r.previous_result_id end,'correctionReason',case when"authorization".current_role(school)in('admin','teacher','coordinator')then correction.reason else null end)||case when r.model='numeric'then jsonb_build_object('score',r.score,'maxScore',r.max_score)else'{}'::jsonb end order by r.id),'[]'::jsonb)into rows from bounded r join app.assessments a on a.school_id=r.school_id and a.id=r.assessment_id join app.school_custom_references ref on ref.school_id=r.school_id and ref.id=r.reference_id left join app.academic_correction_records correction on correction.school_id=r.school_id and correction.result_id=r.id;
 if octet_length(rows::text)>500000 then raise exception 'Academic history requires a smaller page'using errcode='22023';end if;select coalesce(jsonb_agg(item order by ordinal),'[]'::jsonb)into items from jsonb_array_elements(rows)with ordinality value(item,ordinal)where ordinal<=page_limit;
 return jsonb_build_object('items',items,'nextCursor',case when jsonb_array_length(rows)>page_limit then items->(page_limit-1)->>'id'else null end);
end$$;
revoke execute on function internal.correct_closed_academic_source(uuid,jsonb),internal.read_academic_revision_page(uuid,integer,uuid),internal.current_submission_academic_guard()from public,anon,authenticated,service_role,cuevo_api,cuevo_worker;
grant execute on function internal.correct_closed_academic_source(uuid,jsonb),internal.read_academic_revision_page(uuid,integer,uuid)to cuevo_api;
commit;
